"""Round-robin job scheduler module."""


def _get_enabled_workers(workers: list[dict]) -> list[str]:
    """Return names of enabled workers."""
    return [w["name"] for w in workers if w.get("enabled", True)]


def _try_assign_job(
    job: str,
    enabled_workers: list[str],
    rr_index: int,
    assigned_counts: dict[str, int],
    capacities: dict[str, int] | None,
) -> tuple[dict | None, int]:
    """Try to assign a job to the next available worker.

    Returns a (result_row_or_None, updated_rr_index) tuple.
    """
    num_workers = len(enabled_workers)
    for _ in range(num_workers):
        worker_name = enabled_workers[rr_index % num_workers]
        rr_index += 1

        if capacities is not None:
            cap = capacities.get(worker_name)
            if cap is not None and assigned_counts[worker_name] >= cap:
                continue

        assigned_counts[worker_name] += 1
        return {"job": job, "worker": worker_name}, rr_index

    return None, rr_index


def _validate_workers(workers: list[dict]) -> None:
    """Validate the workers list and each worker entry."""
    if not isinstance(workers, list):
        raise TypeError(f"workers must be a list, got {type(workers).__name__!r}")
    for idx, worker in enumerate(workers):
        if not isinstance(worker, dict):
            raise TypeError(
                f"Each worker must be a dict; workers[{idx}] is "
                f"{type(worker).__name__!r}"
            )
        if "name" not in worker:
            raise ValueError(f"workers[{idx}] is missing required 'name' field")
        if not isinstance(worker["name"], str):
            raise TypeError(
                f"workers[{idx}]['name'] must be a str, got "
                f"{type(worker['name']).__name__!r}"
            )
        if not worker["name"]:
            raise ValueError(f"workers[{idx}]['name'] must not be an empty string")
        if "enabled" in worker and not isinstance(worker["enabled"], bool):
            raise TypeError(
                f"workers[{idx}]['enabled'] must be a bool, got "
                f"{type(worker['enabled']).__name__!r}"
            )


def _validate_jobs(jobs: list[str]) -> None:
    """Validate the jobs list and each job entry."""
    if not isinstance(jobs, list):
        raise TypeError(f"jobs must be a list, got {type(jobs).__name__!r}")
    for idx, job in enumerate(jobs):
        if not isinstance(job, str):
            raise TypeError(
                f"Each job must be a str; jobs[{idx}] is "
                f"{type(job).__name__!r}"
            )


def _validate_capacities(
    capacities: dict[str, int] | None, enabled_workers: list[str]
) -> None:
    """Validate the capacities mapping if provided."""
    if capacities is None:
        return
    if not isinstance(capacities, dict):
        raise TypeError(
            f"capacities must be a dict or None, got {type(capacities).__name__!r}"
        )
    for key, value in capacities.items():
        if not isinstance(key, str):
            raise TypeError(
                f"capacities keys must be str, got {type(key).__name__!r}"
            )
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError(
                f"capacities[{key!r}] must be an int, got "
                f"{type(value).__name__!r}"
            )
        if value < 0:
            raise ValueError(
                f"capacities[{key!r}] must be non-negative, got {value}"
            )


def assign_round_robin(
    workers: list[dict],
    jobs: list[str],
    capacities: dict[str, int] | None = None,
) -> list[dict]:
    """Assign jobs to enabled workers in round-robin order.

    Args:
        workers: List of worker dicts with "name" and optional "enabled" fields.
        jobs: List of job names to assign.
        capacities: Optional mapping of worker name to maximum job count.
            Workers missing from the mapping have no cap. Jobs that would
            exceed all remaining capacities are omitted.

    Returns:
        List of dicts shaped as {"job": str, "worker": str}.

    Raises:
        TypeError: If arguments are of the wrong type.
        ValueError: If there are no enabled workers, or required fields are
            missing or invalid.
    """
    _validate_workers(workers)
    _validate_jobs(jobs)

    enabled_workers = _get_enabled_workers(workers)

    if not enabled_workers:
        raise ValueError("No enabled workers available.")

    _validate_capacities(capacities, enabled_workers)

    assigned_counts: dict[str, int] = {name: 0 for name in enabled_workers}

    result = []
    rr_index = 0

    for job in jobs:
        row, rr_index = _try_assign_job(
            job, enabled_workers, rr_index, assigned_counts, capacities
        )
        if row is not None:
            result.append(row)

    return result

